#include <biglybtc/tag_runtime_registry.hpp>
#include <biglybtc/tag_constraints.hpp>
#include <biglybtc/tag_named_metrics.hpp>
#include <biglybtc/bencode.hpp>
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>
namespace b=biglybtc::core;namespace r=b::tags::runtime;namespace c=b::tags::constraints;
namespace {
void need(bool value,const char* message){if(!value){throw std::runtime_error(message);}}
std::vector<r::Type> roster(int mask,bool duplicate){std::vector<r::Type> result;
 for(int id=1;id<=7;++id){r::Type type;type.id=id;type.complete=true;if(mask&(1<<(id-1))){type.tags.push_back({1,id==4?4:2,u"Generated symbol",{},true,r::Membership::Unknown});if(duplicate){auto extra=type.tags.front();extra.id=2;type.tags.push_back(extra);}}result.push_back(std::move(type));}return result;}
void actualConstructors(){std::ifstream file(CONSTRAINT_NAME_CENSUS_FIXTURE,std::ios::binary);auto fixture=b::Document::parse(std::string{std::istreambuf_iterator<char>(file),{}});need(bool(fixture),"Actual constructor census fixture");unsigned cases=0;
 for(const auto& row:fixture->find("rows")->children){const int mask=int(row.find("mask")->integer);const bool duplicate=row.find("duplicate")->integer!=0;auto registry=r::Registry::create(roster(mask,duplicate),false);need(bool(registry),"Generated observed roster");auto selected=registry->lookupConstraintName(u"Generated symbol");need(bool(selected),"Observed eligible name selection");std::vector<std::int64_t> ids;for(const auto& ref:selected->tags){ids.push_back(ref.uid());}std::ranges::sort(ids);const auto& actual=row.find("dependent_uids")->children;need(ids.size()==actual.size(),"Actual constructor eligible dependency count differs");for(std::size_t i=0;i<ids.size();++i){need(ids[i]==actual[i].integer,"Actual constructor feature/first-per-type filter differs");}need(selected->complete==(!duplicate||ids.empty()),"Duplicate aliases admitted a unique census");need(!registry->lookupName(u"Generated symbol")->complete,"Partial census became globally complete");++cases;
 }need(cases==254,"Actual constructor cases lost");}
void incompleteSourcesAndFeaturelessAliases(){auto source=roster(4|32|64,false);auto registry=r::Registry::create(source,false);auto selected=registry->lookupConstraintName(u"Generated symbol");need(selected&&selected->complete&&selected->tags.size()==1&&selected->tags[0].type==3,"Featureless alias masked actual property dependency");
 for(unsigned missing=0;missing<5;++missing){auto incomplete=source;incomplete.erase(incomplete.begin()+missing);auto view=r::Registry::create(std::move(incomplete),false);need(view&&!view->lookupConstraintName(u"Generated symbol")->complete,"Missing family became a complete census");incomplete=source;incomplete[missing].complete=false;view=r::Registry::create(std::move(incomplete),false);need(view&&!view->lookupConstraintName(u"Generated symbol")->complete,"Partial family became a complete census");}
 source[0].tags.push_back({1,2,{}, {},true,r::Membership::Unknown});registry=r::Registry::create(source,false);need(registry&&!registry->lookupConstraintName(u"Generated symbol")->complete,"Unknown eligible name was ignored");source=roster(4,false);source.push_back({8,{},true});registry=r::Registry::create(source,false);need(registry&&!registry->lookupConstraintName(u"Generated symbol")->complete,"Future feature family was silently excluded");
 source=roster(4|32|64,false);source[2].tags[0].membership=r::Membership::Present;registry=r::Registry::create(source,false);c::Facts facts;facts.tagRegistry=*registry;c::NamedTagMetric metric;metric.uid=(std::int64_t{3}<<32)|1;metric.count=7;facts.namedTagMetrics=std::make_shared<const c::NamedTagMetrics>(*c::NamedTagMetrics::create({metric}));auto expression=c::compile(u"countTag(\"Generated symbol\")==7");auto value=c::evaluate(*expression,facts);need(value&&std::get<bool>(*value),"Qualified unique partial-source count was refused");facts.namedTagMetrics.reset();value=c::evaluate(*expression,facts);need(!value&&value.error().kind==c::ProblemKind::Unavailable,"A name census invented metric values");}
void parsedDemandAndBounds(){auto expression=c::compile(u"countTag(\"Generated symbol\")>=0&&hasTagAge(\"Generated symbol\")>=0&&tagPosition(\"Generated symbol\",2)>=-1&&hasTag(\"Other\")");need(bool(expression)&&expression->namedTagRequests().size()==1,"Parsed named demand did not merge");const auto& demand=expression->namedTagRequests()[0];need(demand.name==u"Generated symbol"&&demand.age&&demand.count&&demand.position,"Named demand lost function kind");auto plain=c::compile(u"hasTag(\"countTag fake\")");need(plain&&plain->namedTagRequests().empty(),"Name text invented a count request");auto registry=r::Registry::create(roster(4,false),false);need(registry&&!registry->lookupConstraintName(std::u16string(4097,u'x')),"Name quota was ignored");}
}
int main(){try{actualConstructors();incompleteSourcesAndFeaturelessAliases();parsedDemandAndBounds();}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}std::cout<<"PASS254 actual constructor name/feature cases;partial-source unique selection,aliases,unknown families and parsed demand bounds\n";}
